/* ❌ OLD: Default font-display is 'auto'/'block'. If network is slow,
   text remains completely invisible for up to 3 seconds (FOIT),
   ruining First Contentful Paint (FCP). */
@font-face {
  font-family: 'BrandFont';
  src: url('/fonts/brand.woff2') format('woff2');
  font-display: block; /* 3-second invisible block period */
}

h1 {
  font-family: 'BrandFont', Arial, sans-serif;
}

/* ✅ NEW: Instant text rendering via 'swap' combined with
   a metric-matched fallback font that eliminates layout shift. */
@font-face {
  font-family: 'BrandFontFallback';
  src: local('Arial');
  size-adjust: 102.5%;
  ascent-override: 94%;
  descent-override: 26%;
  line-gap-override: 0%;
}

@font-face {
  font-family: 'BrandFont';
  src: url('/fonts/brand.woff2') format('woff2');
  font-display: swap;
}

h1 {
  font-family: 'BrandFont', 'BrandFontFallback', sans-serif;
}
